import {EmployeeClient} from '../../employee-client/server.mjs';
import {readFile,writeFile} from 'node:fs/promises';import {createHash,randomUUID} from 'node:crypto';
if(!process.env.QA_ROOT?.startsWith('/tmp/')||!process.env.QA_HOST?.startsWith('http://127.0.0.1:'))throw Error('Temporary local fixture only');
const s=JSON.parse(await readFile(process.env.QA_AUTH,'utf8')),host=process.env.QA_HOST,cookie=s.cookies.worker,headers={cookie,'x-orbit-project-id':String(s.project)};const info=await(await fetch(host+'/api/offline-info',{headers})).json(),detail=await(await fetch(host+'/api/cross-records?id='+s.reviewTarget,{headers})).json();
const app=new EmployeeClient(process.env.QA_ROOT,{port:0}),store=app.store,ns=info.serverId+':'+s.worker;store.login(ns,{id:s.worker,displayName:'测试制作人'},cookie,host);store.set('protocol:'+ns,2);store.set('allowed-projects:'+ns,[s.project]);store.set('catalog:'+ns,[{id:s.project,name:'验收项目',projectType:'cross_border',permissions:['cross.view','cross.create','cross.edit']}]);store.set('shell-ready:'+ns,true);store.set('lastFullAudit:'+ns,Date.now());store.set('lastSync:'+ns,Date.now());const device='actual-browser-'+randomUUID();store.set('device-id:'+ns,device);app.online=true;app.sync=async()=>{};app.cacheWorker=async()=>{};
const parent=randomUUID(),child=randomUUID(),files=detail.files.map(f=>({name:f.file_name,mime:f.mime_type,size:f.file_size,retainedId:f.id})),base={entity:'cross:'+s.reviewTarget,kind:'mother',title:'员工实际未同步的母版',data:{keywords:'本地仍需保留的修改'},target:{id:s.reviewTarget,revision:Math.max(0,detail.row.revision-1),base:{updatedAt:detail.row.updated_at}},files};
const png=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aWQAAAABJRU5ErkJggg==','base64');base.files.push({name:'本地附件.png',mime:'image/png',size:png.length,localFileId:-9001});const d2={...base,title:'关联的后续本地修改',dependsOn:parent,files:base.files.map(f=>f.localFileId?{name:f.name,mime:f.mime,size:f.size,retainedId:f.localFileId}:f)};
for(const [id,d] of [[parent,base],[child,d2]])store.db.prepare("INSERT INTO jobs(ns,id,project,json,state,error,created) VALUES(?,?,?,?,'blocked','主机版本已更新，需要核对',?)").run(ns,id,s.project,JSON.stringify(d),Date.now());const path=store.queuePath(ns,parent,files.length-1);await writeFile(path,png);store.db.prepare('INSERT INTO job_files VALUES(?,?,?,?,?,?)').run(ns,parent,files.length-1,path,createHash('sha256').update(png).digest('hex'),png.length);store.db.prepare('INSERT INTO local_records VALUES(?,?,?,?,?,?)').run(ns,base.entity,s.project,child,'mother',JSON.stringify({row:{...detail.row,title:d2.title},files:detail.files}));
const bridge=await readFile(new URL('../../employee-client/ui/bridge.js',import.meta.url),'utf8');const behavior=`document.getElementById('edit').onclick=()=>{const f=document.createElement('form');f.className='cross-edit-page';const label=document.createElement('label');label.textContent='员工未保存的输入';const input=document.createElement('input');input.id='unsaved';label.append(input);f.append(label);document.getElementById('editor').append(f);};document.getElementById('save').onclick=()=>{window.savedEditorValue=document.getElementById('unsaved')?.value;document.getElementById('editor').replaceChildren();};`;app.original.serveRoot=async(req,res)=>{res.writeHead(200,{'content-type':'text/html; charset=utf-8','set-cookie':'orbit_local='+app.token+'; Path=/; SameSite=Strict'});res.end('<!doctype html><meta charset="utf-8"><title>员工端同步验收</title><body style="font:16px system-ui;padding:24px;background:#f5f7fb"><h1>员工正在使用的页面</h1><p>此页面用于验证同步处理不会关闭编辑或丢失输入。</p><button id="edit">开始本地编辑</button><button id="save">保存并退出编辑</button><div id="editor"></div><script>'+behavior+'</script><script data-token="'+app.token+'">'+bridge+'</script>');};
await app.start();app.port=app.server.address().port;clearInterval(app.controlTimer);app.controlTimer=setInterval(()=>void app.control.tick(),500);await writeFile(process.env.QA_READY,JSON.stringify({url:'http://127.0.0.1:'+app.port,device,parent,child,path,ns}));process.on('SIGTERM',async()=>{await app.close();process.exit(0);});
